#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

    /// Takes a slice of 32‐bit integers `numbers` and a 32‐bit integer `delim`,
    /// and returns a new `Vec<i32>` in which `delim` has been interspersed
    /// between every two consecutive elements of `numbers`.
    /// 
    /// If `numbers` is empty, the result is empty.
    /// Otherwise, if `numbers.len() == n > 0`, the result has length `2*n - 1`,
    /// and for each index `j < result.len()`:
    ///   - if `j` is even, `result[j] == numbers[j/2]`
    ///   - if `j` is odd,  `result[j] == delim`
    fn intersperse(numbers: &[i32], delim: i32) -> (res: Vec<i32>)
        ensures
            // final length is 0 when input is empty, else 2*n-1
            res@.len() == if numbers@.len() == 0 {
                0
            } else {
                2 * numbers@.len() - 1
            }
            // even indices reproduce the input, odd indices are delim
            && forall j: usize :: j < res@.len() ==>
                if j % 2 == 0 {
                    res@.index(j) == numbers@.index(j / 2)
                } else {
                    res@.index(j) == delim
                }
    {
        let n = numbers.len();
        // allocate exactly the needed capacity
        let mut res = Vec::with_capacity(if n == 0 { 0 } else { 2 * n - 1 });

        let mut i: usize = 0;
        while i < n
            invariant
                // 0 <= i <= n
                i <= n
            invariant
                // after processing i input‐elements, res.len() == 0                if i==0,
                // else 2*i - 1
                res@.len() == if i == 0 {
                    0
                } else {
                    2 * i - 1
                }
            invariant
                // and the prefix of res is correct
                forall j: usize :: j < res@.len() ==>
                    if j % 2 == 0 {
                        res@.index(j) == numbers@.index(j / 2)
                    } else {
                        res@.index(j) == delim
                    }
            decreases n - i
        {
            // push the next original element
            res.push(numbers[i]);
            // if not the last, push a delimiter
            if i + 1 < n {
                res.push(delim);
            }
            i += 1;
        }

        // return the built vector
        res
    }

}